def _merge_fake_deltas(
    accumulated: DeltaMessage | None, new: DeltaMessage | None
) -> DeltaMessage | None:
    """Fold one token's worth of `_FakeParser` output into a per call
    accumulator, the same way a real parser merges multiple tokens'
    effects into the single `DeltaMessage` it returns per `parse_delta`
    call.
    """
    if new is None:
        return accumulated
    if accumulated is None:
        accumulated = DeltaMessage()

    if new.content:
        accumulated.content = (accumulated.content or "") + new.content
    if new.reasoning:
        accumulated.reasoning = (accumulated.reasoning or "") + new.reasoning

    for tc in new.tool_calls:
        starts_new_call = tc.id is not None or (
            tc.function is not None and tc.function.name is not None
        )
        existing = (
            None
            if starts_new_call
            else next((t for t in accumulated.tool_calls if t.index == tc.index), None)
        )
        if existing is None:
            accumulated.tool_calls.append(tc)
            continue
        if existing.function is None:
            existing.function = DeltaFunctionCall()
        if tc.function is not None and tc.function.arguments:
            existing.function.arguments = (
                existing.function.arguments or ""
            ) + tc.function.arguments

    return accumulated

class _FakeToolParser:
    """Tool parser slot filler so `tool_choice="auto"` keeps tool calls."""

    engine_based_streaming = True

    def __init__(self, tokenizer, tools):
        pass

class _FakeParser(Parser):
    """Deterministic `Parser` stub for unit testing the replay/merge/pin
    mechanics of `OnlineDerenderer._derender_chat_stream_parsed` in
    isolation from any real reasoning/tool parser's markup grammar.

    Processes every id in `delta_token_ids` in order and folds their
    effects into one `DeltaMessage`, like a real parser handling a
    multi-token delta in a single call. Ignores `delta_text`:

    - `TOOL_START` opens a new tool call at index 0 (id + name).
    - `TOOL_ARG` appends one `"a"` to that tool call's arguments.
    - `REASON` emits one `"r"` of reasoning (suppressed when the request
      has `include_reasoning=False`, mirroring the real parsers).
    - `CONTENT` emits one `"c"` of content.
    - An empty `delta_token_ids` with `finished=True` (the finish only
      flush call) emits a `"FLUSH"` content sentinel so tests can confirm
      it happened.
    - Anything else emits nothing.
    """

    tool_parser_cls = _FakeToolParser  # type: ignore[assignment]

    TOOL_START = 9
    TOOL_ARG = 10
    REASON = 11
    CONTENT = 12

    def parse_delta(
        self,
        delta_text,
        delta_token_ids,
        request,
        prompt_token_ids=None,
        *,
        finished,
    ):
        if not delta_token_ids:
            return DeltaMessage(content="FLUSH") if finished else None

        accumulated: DeltaMessage | None = None
        for tok in delta_token_ids:
            accumulated = _merge_fake_deltas(
                accumulated, self._parse_one_token(tok, request)
            )
        return accumulated

    def _parse_one_token(self, tok: int, request) -> DeltaMessage | None:
        if tok == self.TOOL_START:
            return DeltaMessage(
                tool_calls=[
                    DeltaToolCall(
                        id=f"call-{random_uuid()}",
                        type="function",
                        function=DeltaFunctionCall(name="get_weather", arguments=""),
                        index=0,
                    )
                ]
            )
        if tok == self.TOOL_ARG:
            return DeltaMessage(
                tool_calls=[
                    DeltaToolCall(index=0, function=DeltaFunctionCall(arguments="a"))
                ]
            )
        if tok == self.REASON:
            if not request.include_reasoning:
                return None
            return DeltaMessage(reasoning="r")
        if tok == self.CONTENT:
            return DeltaMessage(content="c")
        return None

def _generate_logprobs(token_ids: list[int]) -> dict:
    """Per-token `GenerateLogProbs` entries (integer token ids, no token or
    bytes), as sent by the generate worker."""
    return {
        "content": [
            {"token_id": tid, "logprob": -0.5, "rank": 1, "top_logprobs": []}
            for tid in token_ids
        ]
    }

def _make_usage_chunk(
    completion_tokens: int,
    prompt_tokens: int = 0,
    request_id: str = "test-req",
) -> GenerateStreamResponse:
    """Build a usage only final SSE chunk (empty choices)."""
    return GenerateTokensStreamResponse(
        request_id=request_id,
        choices=[],
        usage=UsageInfo(
            prompt_tokens=prompt_tokens,
            completion_tokens=completion_tokens,
            total_tokens=prompt_tokens + completion_tokens,
        ),
    )

def tokenizer():
    """Load the tiny tokenizer used across unit tests."""
    return get_tokenizer(MODEL_NAME)

def _decode_stream_expected(
    tokenizer, prompt_ids: list[int], output_ids: list[int]
) -> str:
    """Engine-equivalent decode via `DecodeStream`, primed by stepping the
    prompt (`DecodeStream(ids=...)` needs tokenizers >= 0.22)."""
    stream = DecodeStream(skip_special_tokens=True)
    for tid in prompt_ids:
        stream.step(tokenizer.backend_tokenizer, tid)
    return "".join(
        s
        for tid in output_ids
        if (s := stream.step(tokenizer.backend_tokenizer, tid)) is not None
    )

def tekken_tokenizer():
    return with_retry(
        lambda: MistralTokenizer.from_pretrained("mistralai/Pixtral-12B-2409"),
        log_msg="Error loading Tekken tokenizer",
    )

class TestSeedStreamState:
    """`_seed_stream_state`: pure helper building the initial decode state."""

    def test_seeds_prev_token_ids_from_prompt_tail(self, tokenizer, leading_space_ids):
        prompt_ids, _, _ = leading_space_ids
        state = _seed_stream_state(tokenizer, prompt_ids, skip_special_tokens=True)
        assert state.prev_token_ids
        assert state.read_offset == len(state.prev_token_ids)

    def test_byte_fallback_survives_state_round_trip(
        self, derenderer, tekken_tokenizer
    ):
        """Byte-fallback pieces in the window must survive the JSON transport,
        whether they come from the prompt tail or from a previous chunk."""
        token_ids = tekken_tokenizer.encode("서울은 맑습니다", add_special_tokens=False)
        fallback_ends = [
            i + 1
            for i, token_id in enumerate(token_ids)
            if "�" in tekken_tokenizer.tokenizer.id_to_piece(token_id)
        ]
        assert fallback_ends

        bos_id = tekken_tokenizer.bos_token_id
        for split in [0, fallback_ends[-1]]:
            state = _seed_stream_state(
                tekken_tokenizer,
                [bos_id, *token_ids[:split]],
                skip_special_tokens=True,
            )
            text = ""
            for token_id in token_ids[split:]:
                state = DerenderStreamState.model_validate_json(state.model_dump_json())
                delta, state = derenderer._detokenize_delta(
                    tekken_tokenizer, [token_id], state
                )
                text += delta
            assert text == tekken_tokenizer.decode(token_ids[split:])

    def test_none_prompt_token_ids_returns_empty_state(self, tokenizer):
        assert (
            _seed_stream_state(tokenizer, None, skip_special_tokens=True)
            == DerenderStreamState()
        )

    def test_empty_prompt_token_ids_returns_empty_state(self, tokenizer):
        assert (
            _seed_stream_state(tokenizer, [], skip_special_tokens=True)
            == DerenderStreamState()
        )

class TestPromptSeededLeadingSpace:
    """Every decode entry point keeps the first token's leading space when
    given prompt_token_ids."""

    @pytest.mark.asyncio
    async def test_chat_batch_seeded_via_explicit_prompt_token_ids(
        self, derenderer, leading_space_ids
    ):
        prompt_ids, output_ids, expected = leading_space_ids
        choices, _ = await derenderer.derender_chat(
            GenerateTokensResponse(
                request_id="t",
                choices=[
                    GenerateTokensChoice(
                        index=0, token_ids=output_ids, finish_reason="stop"
